CREATE OR ALTER VIEW stg.v_Normalizada AS SELECT CONVERT(nvarchar(260),r.id_lote) archivo,r.fila_origen fila_archivo,r.id_raw,r.clave_origen,r.version_origen,TRY_CONVERT(int,ANIO) AS anio_num,TRY_CONVERT(int,MES) AS mes_num,TRY_CONVERT(bigint,NULLIF(LTRIM(RTRIM(ATENCIONES)),N'')) AS atenciones_num,ANIO AS anio_original,MES AS mes_original,ATENCIONES AS atenciones_original,COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([REGION],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [REGION],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([PROVINCIA],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [PROVINCIA],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([UBIGEO_DISTRITO],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [UBIGEO_DISTRITO],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([DISTRITO],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [DISTRITO],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([COD_UNIDAD_EJECUTORA],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [COD_UNIDAD_EJECUTORA],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([DESC_UNIDAD_EJECUTORA],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [DESC_UNIDAD_EJECUTORA],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([COD_IPRESS],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [COD_IPRESS],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([IPRESS],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [IPRESS],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([NIVEL_EESS],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [NIVEL_EESS],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([PLAN_SEGURO],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [PLAN_SEGURO],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([COD_SERVICIO],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [COD_SERVICIO],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([DESC_SERVICIO],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [DESC_SERVICIO],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([SEXO],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [SEXO],COALESCE(NULLIF(UPPER(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE([GRUPO_EDAD],NCHAR(160),N' '),CHAR(9),N' '),CHAR(13),N' '),CHAR(10),N' ')))),N''),N'NO INFORMADO') AS [GRUPO_EDAD] FROM raw.Registros r WHERE r.id_lote=TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N'Lote')) AND r.operacion='U' AND (r.fuente_tipo='SNAPSHOT' OR NOT EXISTS(SELECT 1 FROM raw.Registros z WHERE z.id_lote=r.id_lote AND z.clave_origen=r.clave_origen AND z.version_origen>r.version_origen));
